// One events.jsonl record per event (schema siem-factory.event/v1). Restore the
// original event exactly as captured; only the index changes, to devlogs.
let rec = null;
try { rec = JSON.parse(__e._raw); } catch (err) { rec = null; }
if (!rec || rec.sf_schema !== 'siem-factory.event/v1' || typeof rec._raw !== 'string' || !(rec._time > 0)) {
  __e.sf_drop_reason = 'not_a_sample_record';
} else {
  __e._raw = rec._raw;
  __e._time = rec._time;                       // original event time, not now
  __e.host = rec.sf_orig_host;
  __e.source = rec.sf_orig_source;
  __e.sourcetype = rec.sf_orig_sourcetype;     // unchanged, so its props apply
  __e.index = 'devlogs';                       // the HEC token allows nothing else
  __e.sf_orig_index = rec.sf_orig_index;
  __e.sf_dataset_id = rec.sf_dataset_id;
  __e.sf_seq = rec.sf_seq;
  __e.sf_run_id = rec.sf_run_id;
  __e.sf_splunk_event_id = rec.sf_splunk_event_id;
  __e.sf_raw_sha256 = rec.sf_raw_sha256;
  if (!/^[A-Za-z0-9][A-Za-z0-9_.-]{0,99}$/.test(String(__e.sf_replay_id || ''))) {
    __e.sf_replay_id = 'manual';
  }
}
